def ghtoken_from_gh() -> str:
    try:
        r = subprocess.run(
            ["gh", "auth", "token", "--hostname", "github.com"],
            check=True,
            stdout=subprocess.PIPE,
            stderr=subprocess.DEVNULL,
            text=True,
        )
    except (subprocess.CalledProcessError, OSError):
        raise GHTokenNotFound()
    else:
        token = _strip_trailing_newlines(r.stdout)
        if token:
            return token
        else:
            raise GHTokenNotFound()


def ghtoken_from_hub() -> str:
    hub_config_path = os.environ.get("HUB_CONFIG", "")
    if hub_config_path == "":
        xdg_config_home = os.environ.get("XDG_CONFIG_HOME", "")
        if xdg_config_home == "":
            xdg_config_home = str(Path.home() / ".config")
        xdg_config_dirs = os.getenv("XDG_CONFIG_DIRS", "")
        if xdg_config_dirs == "":
            xdg_config_dirs = "/etc/xdg"
        for config_dir in [xdg_config_home, *xdg_config_dirs.split(":")]:
            path = Path(config_dir, "hub")
            if path.exists():
                hub_config_path = str(path)
                break
        else:
            raise GHTokenNotFound()
    try:
        with open(hub_config_path, encoding="utf-8") as fp:
            data = YAML(typ="safe").load(fp)
    except Exception:
        raise GHTokenNotFound()
    try:
        token = data["github.com"][0]["oauth_token"]
    except (TypeError, AttributeError, LookupError):
        raise GHTokenNotFound()
    if isinstance(token, str) and token != "":
        return token
    else:
        raise GHTokenNotFound()


def ghtoken_from_hub_oauthtoken() -> str:
    try:
        r = subprocess.run(
            ["git", "config", "--get", "hub.oauthtoken"],
            check=True,
            stdout=subprocess.PIPE,
            stderr=subprocess.DEVNULL,
            text=True,
        )
    except (subprocess.CalledProcessError, OSError):
        raise GHTokenNotFound()
    else:
        token = _strip_trailing_newlines(r.stdout)
        if token:
            try:
                r2 = subprocess.run(
                    [
                        "git",
                        "config",
                        "--get",
                        "--default",
                        "https://api.github.com",
                        "hub.baseurl",
                    ],
                    check=True,
                    stdout=subprocess.PIPE,
                    stderr=subprocess.DEVNULL,
                    text=True,
                )
            except (subprocess.CalledProcessError, OSError):
                raise GHTokenNotFound()
            baseurl = _strip_trailing_newlines(r2.stdout)
            if baseurl == "https://api.github.com":
                if token.startswith("!"):
                    # Execute the command after '!'
                    try:
                        r3 = subprocess.run(
                            token[1:],
                            shell=True,
                            check=True,
                            stdout=subprocess.PIPE,
                            text=True,
                        )
                        return r3.stdout.strip()
                    except (subprocess.CalledProcessError, OSError):
                        raise GHTokenNotFound()
                else:
                    return token
        raise GHTokenNotFound()


def _strip_trailing_newlines(s: str) -> str:
    return s.rstrip('\r\n')

